export const HOME_PAGE = ALL_PAGES.find(p => p.url === '/')!;
export const FAQ_PAGE = ALL_PAGES.find(p => p.url === '/faq/')!;
export const CONTACT_PAGE = ALL_PAGES.find(p => p.url === '/contact-us/')!;

export function getPageByUrl(url: string): SitePage | undefined {
  const normalized = url.endsWith('/') ? url : url + '/';
  return ALL_PAGES.find(p => p.url === normalized) || ALL_BLOGS.find(b => b.url === normalized);
}

export function getBlogBySlug(slug: string): SitePage | undefined {
  const url = `/blog/${slug}/`;
  return ALL_BLOGS.find(b => b.url === url);
}
